<!-- svelte-ignore state_referenced_locally -->
<script lang="ts">import { useCollaborationContext } from "./CollaborationContext.js";
import { getEditor } from "../../composerContext.js";
import {
  createBinding
} from "@lexical/yjs";
import { onMount } from "svelte";
import YjsCollaboration from "./YjsCollaboration.svelte";
import YjsHistory from "./YjsHistory.svelte";
import YjsFocusTracking from "./YjsFocusTracking.svelte";
const editor = getEditor();
let {
  id = editor.getKey(),
  providerFactory,
  shouldBootstrap,
  username = void 0,
  cursorColor = void 0,
  cursorsContainerRef = null,
  initialEditorState = null,
  excludedProperties = void 0,
  awarenessData = void 0,
  syncCursorPositionsFn = void 0
} = $props();
const collabContext = useCollaborationContext(username, cursorColor);
const { yjsDocMap, name, color } = collabContext;
const provider = providerFactory(id, yjsDocMap);
const doc = yjsDocMap.get(id);
const binding = createBinding(
  editor,
  provider,
  id,
  doc,
  yjsDocMap,
  excludedProperties
);
collabContext.clientID = binding.clientID;
collabContext.isCollabActive = true;
onMount(() => {
  return () => {
    if (editor._parentEditor == null) {
      collabContext.isCollabActive = false;
    }
  };
});
</script>

<YjsCollaboration
  {editor}
  {id}
  {provider}
  {binding}
  docMap={yjsDocMap}
  {name}
  {color}
  {shouldBootstrap}
  {cursorsContainerRef}
  {initialEditorState}
  {awarenessData}
  {syncCursorPositionsFn} />

<YjsHistory {editor} {binding} />
<YjsFocusTracking {editor} {provider} {name} {color} {awarenessData} />
