<script lang="ts">import { onMount } from "svelte";
import { getEditor } from "../../composerContext.js";
import { COMMAND_PRIORITY_HIGH } from "lexical";
const editor = getEditor();
let { loggedCommands = $bindable([]) } = $props();
onMount(() => {
  const unregisterCommandListeners = /* @__PURE__ */ new Set();
  let i = 0;
  for (const [command] of editor._commands) {
    unregisterCommandListeners.add(
      editor.registerCommand(
        command,
        (payload) => {
          i += 1;
          const entry = {
            index: i,
            payload,
            type: command.type ? command.type : "UNKNOWN"
          };
          queueMicrotask(() => {
            const newState = [...loggedCommands, entry];
            if (newState.length > 10) {
              newState.shift();
            }
            loggedCommands = newState;
          });
          return false;
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }
  return () => unregisterCommandListeners.forEach((unregister) => unregister());
});
</script>
