<script lang="ts">import {
  $isCodeNode as isCodeNode,
  CODE_LANGUAGE_FRIENDLY_NAME_MAP,
  getLanguageFriendlyName
} from "@lexical/code";
import { $getNodeByKey as getNodeByKey } from "lexical";
import { getContext } from "svelte";
import { getActiveEditor, getIsEditable } from "../../core/composerContext.js";
import DropDown from "../generic/dropdown/DropDown.svelte";
import DropDownItem from "../generic/dropdown/DropDownItem.svelte";
const activeEditor = getActiveEditor();
const isEditable = getIsEditable();
const selectedElementKey = getContext("selectedElementKey");
const codeLanguage = getContext("codeLanguage");
const CODE_LANGUAGE_OPTIONS = getCodeLanguageOptions();
function getCodeLanguageOptions() {
  const options = [];
  for (const [lang, friendlyName] of Object.entries(
    CODE_LANGUAGE_FRIENDLY_NAME_MAP
  )) {
    options.push([lang, friendlyName]);
  }
  return options;
}
function onCodeLanguageSelect(value) {
  $activeEditor.update(() => {
    if ($selectedElementKey !== null) {
      const node = getNodeByKey($selectedElementKey);
      if (isCodeNode(node)) {
        node.setLanguage(value);
      }
    }
  });
}
</script>

<DropDown
  disabled={!$isEditable}
  buttonClassName="toolbar-item code-language"
  buttonLabel={getLanguageFriendlyName($codeLanguage)}
  buttonAriaLabel="Select language">
  <!-- eslint-disable-next-line svelte/require-each-key -->
  {#each CODE_LANGUAGE_OPTIONS as [value, name]}
    <DropDownItem
      class={`item ${
        value === $codeLanguage ? 'active dropdown-item-active' : ''
      }`}
      onclick={() => onCodeLanguageSelect(value)}>
      <span class="text">{name}</span>
    </DropDownItem>
  {/each}
</DropDown>
