<!--
@component
Modal Dialog for inserting Bluesky posts into the editor.

Call `editor.extensions.openInsertBlueskyDialog()` to open the dialog.

Only one instance of this component should be instantiated per editor.
-->
<script lang="ts">import CloseCircleButton from "../../generic/button/CloseCircleButton.svelte";
import ModalDialog from "../../generic/dialog/ModalDialog.svelte";
import TextInput from "../../generic/input/TextInput.svelte";
import { FocusEditor, insertBlueskyPost } from "../../../core/commands/commands.js";
import { getEditor } from "../../../core/composerContext.js";
import { tick } from "svelte";
let editor = getEditor();
let showModal = $state(false);
export function open() {
  showModal = true;
}
async function close() {
  showModal = false;
  await tick();
  FocusEditor(editor);
}
async function insertBluesky() {
  insertBlueskyPost(editor, post);
  close();
}
export const parseUrl = (str) => {
  const url2 = safe_parse_url(str);
  if (!url2) {
    return null;
  }
  let match;
  if (url2.host === "bsky.app" || url2.host === "staging.bsky.app" || url2.host === "main.bsky.dev") {
    if (match = /^\/profile\/([^/]+)\/post\/([^/]+)\/?$/.exec(url2.pathname)) {
      if (!is_at_identifier(match[1]) || !is_tid(match[2])) {
        return null;
      }
      return { profile: match[1], postKey: match[2] };
    }
  }
  return null;
};
const safe_parse_url = (str) => {
  let url2;
  if ("parse" in URL) {
    url2 = URL.parse(str);
  } else {
    try {
      url2 = new URL(str);
    } catch {
      url2 = null;
    }
  }
  if (url2 && (url2.protocol === "https:" || url2.protocol === "http:")) {
    return url2;
  }
  return null;
};
export const TID_RE = /^[234567abcdefghij][234567abcdefghijklmnopqrstuvwxyz]{12}$/;
export const is_tid = (str) => {
  return str.length === 13 && TID_RE.test(str);
};
export const DID_RE = /^did:([a-z]+):([a-zA-Z0-9._:%-]*[a-zA-Z0-9._-])$/;
export const is_did = (str) => {
  return str.length >= 7 && str.length <= 2048 && DID_RE.test(str);
};
export const HANDLE_RE = /^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$/;
export const is_handle = (str) => {
  return str.length >= 3 && str.length <= 253 && HANDLE_RE.test(str);
};
const is_at_identifier = (str) => {
  return is_did(str) || is_handle(str);
};
let url = $state("");
let post = $derived.by(() => parseUrl(url));
let isDisabled = $derived.by(() => !post);
editor.extensions.openInsertBlueskyDialog = open;
</script>

<ModalDialog bind:showModal>
  <CloseCircleButton onclick={close} />
  <div class="modal">
    <h2 class="Modal__title">Embed Bluesky Post</h2>
    <div class="Modal__content">
      <TextInput
        label="Bluesky URL"
        placeholder="i.e. https://bsky.app/profile/syedumar.bsky.social/post/3lktvwrbcic25"
        bind:value={url}
        dataTestId="bluesky-embed-modal-url" />
      <div class="DialogActions">
        <button
          type="button"
          data-test-id="bluesky-embed-modal-submit-btn"
          disabled={isDisabled}
          class="Button__root"
          class:Button__disabled={isDisabled}
          onclick={insertBluesky}>
          Confirm
        </button>
      </div>
    </div>
  </div>
</ModalDialog>

<style>
  .modal {
    width: 30em;
  }
</style>
