<script lang="ts">import { getContext } from "svelte";
import { getActiveEditor, getIsEditable } from "../../core/composerContext.js";
import { SHORTCUTS } from "./shortcuts.js";
import { toggleUnderline } from "../../core/commands/commands.js";
const activeEditor = getActiveEditor();
const isEditable = getIsEditable();
const isUnderline = getContext("isUnderline");
</script>

<button
  disabled={!$isEditable}
  onclick={() => {
    toggleUnderline($activeEditor);
  }}
  class={'toolbar-item spaced ' + ($isUnderline ? 'active' : '')}
  title={`Underline (${SHORTCUTS.UNDERLINE})`}
  type="button"
  aria-label={`Format text to underlined. Shortcut: ${SHORTCUTS.UNDERLINE}`}>
  <i class="format underline"></i>
</button>
