<script lang="ts">import { CAN_USE_DOM } from "@lexical/utils";
import DropDownItems from "./DropDownItems.svelte";
import Portal from "../portal/Portal.svelte";
import { isDOMNode } from "lexical";
let {
  disabled = false,
  buttonAriaLabel = void 0,
  buttonClassName,
  buttonIconClassName = void 0,
  buttonLabel = void 0,
  stopCloseOnClickSelf = false,
  title = void 0,
  children,
  target = void 0
} = $props();
let dropDownRef = $state();
let buttonRef = $state();
let showDropDown = $state(false);
function handleClose() {
  showDropDown = false;
  if (buttonRef) {
    buttonRef.focus();
  }
}
$effect(() => {
  if (!CAN_USE_DOM) return;
  if (!showDropDown) return;
  if (!buttonRef || !dropDownRef) return;
  const { top, left } = buttonRef.getBoundingClientRect();
  dropDownRef.style.top = `${top + 42}px`;
  dropDownRef.style.left = `${Math.min(
    left,
    window.innerWidth - dropDownRef.offsetWidth - 20
  )}px`;
});
const handle = (event) => {
  const target2 = event.target;
  if (!isDOMNode(target2)) {
    return;
  }
  if (stopCloseOnClickSelf) {
    if (dropDownRef && dropDownRef.contains(target2)) return;
  }
  if (buttonRef && !buttonRef.contains(target2)) {
    showDropDown = false;
  }
};
$effect(() => {
  if (!CAN_USE_DOM) return;
  if (!showDropDown) return;
  document.addEventListener("click", handle);
  return () => document.removeEventListener("click", handle);
});
</script>

<button
  type="button"
  {disabled}
  aria-label={buttonAriaLabel || buttonLabel}
  class={buttonClassName}
  onclick={() => (showDropDown = !showDropDown)}
  bind:this={buttonRef}
  {title}>
  {#if buttonIconClassName}
    <span class={buttonIconClassName}></span>
  {/if}

  {#if buttonLabel}
    <span class="text dropdown-button-text">{buttonLabel}</span>
  {/if}

  <i class="chevron-down"></i>
</button>

{#if showDropDown}
  <Portal {target}>
    <DropDownItems bind:dropDownRef onClose={handleClose}>
      {@render children?.()}
    </DropDownItems>
  </Portal>
{/if}
