<!--
@component
Modal Dialog for inserting tables into the editor.

Call `editor.extensions.openInsertTweetDialog()` to open the dialog.

Only one instance of this component should be instantiated per editor.
-->
<script lang="ts">import CloseCircleButton from "../../generic/button/CloseCircleButton.svelte";
import ModalDialog from "../../generic/dialog/ModalDialog.svelte";
import TextInput from "../../generic/input/TextInput.svelte";
import { FocusEditor, insertTweet } from "../../../core/commands/commands.js";
import { getEditor } from "../../../core/composerContext.js";
import { tick } from "svelte";
let url = $state("");
let id = $derived.by(() => parseUrl(url));
let isDisabled = $derived.by(() => !id);
let editor = getEditor();
let showModal = $state(false);
export function open() {
  showModal = true;
}
async function close() {
  showModal = false;
  await tick();
  FocusEditor(editor);
}
async function onSubmit() {
  insertTweet(editor, id);
  close();
}
function parseUrl(url2) {
  const match = /^https:\/\/(twitter|x)\.com\/(#!\/)?(\w+)\/status(es)*\/(\d+)/.exec(url2);
  if (match != null) {
    return match[5];
  }
  return null;
}
editor.extensions.openInsertTweetDialog = open;
</script>

<ModalDialog bind:showModal>
  <CloseCircleButton onclick={close} />
  <div class="modal">
    <h2 class="Modal__title">Embed Tweet</h2>
    <div class="Modal__content">
      <TextInput
        label="Tweet URL"
        placeholder="i.e. https://x.com/umaranis/status/1904831197710000491"
        bind:value={url}
        dataTestId="tweet-embed-modal-url" />
      <div class="DialogActions">
        <button
          type="button"
          data-test-id="tweet-embed-modal-submit-btn"
          disabled={isDisabled}
          class="Button__root"
          class:Button__disabled={isDisabled}
          onclick={onSubmit}>
          Confirm
        </button>
      </div>
    </div>
  </div>
</ModalDialog>

<style>
  .modal {
    width: 30em;
  }
</style>
