<script lang="ts">import BlockWithAlignableContents from "../BlockWithAlignableContents.svelte";
let isTwitterScriptLoading = true;
const WIDGET_SCRIPT_URL = "https://platform.twitter.com/widgets.js";
let {
  className,
  format,
  loadingComponent,
  nodeKey,
  onError,
  onLoad,
  tweetID
} = $props();
let containerRef = null;
let previousTweetIDRef = "";
let isTweetLoading = $state(false);
const createTweet = async () => {
  try {
    await window.twttr.widgets.createTweet(tweetID, containerRef);
    isTweetLoading = false;
    isTwitterScriptLoading = false;
    if (onLoad) {
      onLoad();
    }
  } catch (error) {
    if (onError) {
      onError(String(error));
    }
  }
};
$effect(() => {
  if (tweetID !== previousTweetIDRef) {
    isTweetLoading = true;
    if (isTwitterScriptLoading) {
      const script = document.createElement("script");
      script.src = WIDGET_SCRIPT_URL;
      script.async = true;
      document.body?.appendChild(script);
      script.onload = createTweet;
      if (onError) {
        script.onerror = (e) => onError(String(e));
      }
    } else {
      createTweet();
    }
    if (previousTweetIDRef) {
      previousTweetIDRef = tweetID;
    }
  }
});
</script>

<BlockWithAlignableContents {className} {format} {nodeKey}>
  {#if isTweetLoading}
    {loadingComponent}
  {/if}
  <div style="display: inline-block; width: 550px" bind:this={containerRef}>
  </div>
</BlockWithAlignableContents>
