<script lang="ts">import { onMount, onDestroy } from "svelte";
let {
  target = globalThis.document?.body,
  children,
  portalRef = $bindable()
} = $props();
onMount(() => {
  if (target) {
    target.appendChild(portalRef);
  }
});
onDestroy(() => {
  if (portalRef?.parentNode) {
    portalRef.parentNode?.removeChild(portalRef);
  }
});
</script>

<div bind:this={portalRef}>
  {@render children?.()}
</div>
