<script lang="ts">let {
  dataTestId = void 0,
  label,
  placeholder = "",
  value = $bindable(),
  id = "",
  onChange = void 0,
  width = void 0
} = $props();
</script>

<div class="Input__wrapper">
  <label class="Input__label" for={id}>{label}</label>
  <input
    type="number"
    class="Input__input"
    style="width: {width};"
    {placeholder}
    bind:value
    data-test-id={dataTestId}
    {id}
    onchange={(e) => {
      if (onChange) {
        /* @ts-ignore TS not supported in Svelte Html */
        onChange(e.target.value);
      }
    }} />
</div>
