<!-- eslint-disable-next-line svelte/no-unused-svelte-ignore -->
<!--svelte-ignore state_referenced_locally -->
<script lang="ts">import {
  $getTableNodeFromLexicalNodeOrThrow as getTableNodeFromLexicalNodeOrThrow,
  $getTableCellNodeFromLexicalNode as getTableCellNodeFromLexicalNode,
  getTableElement,
  TableCellNode,
  TableObserver,
  getTableObserverFromTableElement,
  $isTableSelection as isTableSelection,
  $isTableCellNode as isTableCellNode
} from "@lexical/table";
import {
  COMMAND_PRIORITY_CRITICAL,
  $getSelection as getSelection,
  $isRangeSelection as isRangeSelection,
  SELECTION_CHANGE_COMMAND
} from "lexical";
import TableActionMenu from "./TableActionMenu.svelte";
import { writable } from "svelte/store";
import { getEditor, getIsEditable } from "../../composerContext.js";
import { mergeRegister } from "@lexical/utils";
import ColorPickerDialog from "../../../components/generic/colorpicker/ColorPickerDialog.svelte";
import { CAN_USE_DOM } from "@lexical/utils";
let { anchorElem, cellMerge } = $props();
const editor = getEditor();
const isEditable = getIsEditable();
let menuButtonRef = $state(null);
let menuRootRef = $state(null);
const isMenuOpen = writable(false);
let tableCellNode = $state(null);
const checkTableCellOverflow = (tableCellParentNodeDOM) => {
  const scrollableContainer = tableCellParentNodeDOM.closest(
    ".PlaygroundEditorTheme__tableScrollableWrapper"
  );
  if (scrollableContainer) {
    const containerRect = scrollableContainer.getBoundingClientRect();
    const cellRect = tableCellParentNodeDOM.getBoundingClientRect();
    const actionButtonRight = cellRect.right - 5;
    const actionButtonLeft = actionButtonRight - 28;
    if (actionButtonRight > containerRect.right || actionButtonLeft < containerRect.left) {
      return true;
    }
  }
  return false;
};
const moveMenu = () => {
  const menu = menuButtonRef;
  const selection = getSelection();
  const nativeSelection = window.getSelection();
  const activeElement = document.activeElement;
  function disable() {
    if (menu) {
      menu.classList.remove("table-cell-action-button-container--active");
      menu.classList.add("table-cell-action-button-container--inactive");
    }
    tableCellNode = null;
  }
  if (selection == null || menu == null) {
    return disable();
  }
  const rootElement = editor.getRootElement();
  let tableObserver = null;
  let tableCellParentNodeDOM = null;
  if (isRangeSelection(selection) && rootElement !== null && nativeSelection !== null && rootElement.contains(nativeSelection.anchorNode)) {
    const tableCellNodeFromSelection = getTableCellNodeFromLexicalNode(
      selection.anchor.getNode()
    );
    if (tableCellNodeFromSelection == null) {
      return disable();
    }
    tableCellParentNodeDOM = editor.getElementByKey(
      tableCellNodeFromSelection.getKey()
    );
    if (tableCellParentNodeDOM == null || !tableCellNodeFromSelection.isAttached()) {
      return disable();
    }
    if (checkTableCellOverflow(tableCellParentNodeDOM)) {
      return disable();
    }
    const tableNode = getTableNodeFromLexicalNodeOrThrow(
      tableCellNodeFromSelection
    );
    const tableElement = getTableElement(
      tableNode,
      editor.getElementByKey(tableNode.getKey())
    );
    if (!tableElement) {
      throw new Error("Expected to find tableElement in DOM");
    }
    tableObserver = getTableObserverFromTableElement(tableElement);
    tableCellNode = tableCellNodeFromSelection;
  } else if (isTableSelection(selection)) {
    const anchorNode = getTableCellNodeFromLexicalNode(
      selection.anchor.getNode()
    );
    if (!isTableCellNode(anchorNode)) {
      throw new Error("TableSelection anchorNode must be a TableCellNode");
    }
    const tableNode = getTableNodeFromLexicalNodeOrThrow(anchorNode);
    const tableElement = getTableElement(
      tableNode,
      editor.getElementByKey(tableNode.getKey())
    );
    if (!tableElement) {
      throw new Error("Expected to find tableElement in DOM");
    }
    tableObserver = getTableObserverFromTableElement(tableElement);
    tableCellParentNodeDOM = editor.getElementByKey(anchorNode.getKey());
    if (tableCellParentNodeDOM === null) {
      return disable();
    }
    if (checkTableCellOverflow(tableCellParentNodeDOM)) {
      return disable();
    }
  } else if (!activeElement) {
    return disable();
  }
  if (tableObserver === null || tableCellParentNodeDOM === null) {
    return disable();
  }
  const enabled = !tableObserver || !tableObserver.isSelecting;
  menu.classList.toggle(
    "table-cell-action-button-container--active",
    enabled
  );
  menu.classList.toggle(
    "table-cell-action-button-container--inactive",
    !enabled
  );
  if (enabled) {
    const tableCellRect = tableCellParentNodeDOM.getBoundingClientRect();
    const anchorRect = anchorElem.getBoundingClientRect();
    const top = tableCellRect.top - anchorRect.top;
    const left = tableCellRect.right - anchorRect.left;
    menu.style.transform = `translate(${left}px, ${top}px)`;
  }
};
$effect(() => {
  let timeoutId = void 0;
  const callback = () => {
    timeoutId = void 0;
    editor.getEditorState().read(moveMenu);
  };
  const delayedCallback = () => {
    if (timeoutId === void 0) {
      timeoutId = setTimeout(callback, 0);
    }
    return false;
  };
  return mergeRegister(
    editor.registerUpdateListener(delayedCallback),
    editor.registerCommand(
      SELECTION_CHANGE_COMMAND,
      delayedCallback,
      COMMAND_PRIORITY_CRITICAL
    ),
    editor.registerRootListener((rootElement, prevRootElement) => {
      if (prevRootElement) {
        prevRootElement.removeEventListener("pointerup", delayedCallback);
      }
      if (rootElement) {
        rootElement.addEventListener("pointerup", delayedCallback);
        delayedCallback();
      }
    }),
    () => clearTimeout(timeoutId)
  );
});
let prevTableCellDOM = $state(tableCellNode);
$effect(() => {
  if (prevTableCellDOM === tableCellNode) return;
  $isMenuOpen = false;
  prevTableCellDOM = tableCellNode;
});
let colorPicker = $state();
</script>

{#if $isEditable}
  <div class="table-cell-action-button-container" bind:this={menuButtonRef}>
    {#if tableCellNode != null}
      <!-- svelte-ignore a11y_consider_explicit_label -->
      <button
        type="button"
        class="table-cell-action-button chevron-down"
        onclick={(e) => {
          e.stopPropagation();
          $isMenuOpen = !$isMenuOpen;
        }}
        bind:this={menuRootRef}>
        <i class="chevron-down"></i>
      </button>
      {#if $isMenuOpen}
        <TableActionMenu
          contextRef={menuRootRef}
          setIsMenuOpen={(val) => ($isMenuOpen = val)}
          onClose={() => ($isMenuOpen = false)}
          _tableCellNode={tableCellNode}
          {cellMerge}
          {colorPicker} />
      {/if}
    {/if}
  </div>
  {#if CAN_USE_DOM}
    <ColorPickerDialog
      title="Cell background color"
      color="white"
      bind:this={colorPicker} />
  {/if}
{/if}
