<!--
  @component ComponentPickerMenuPlugin

  A typeahead menu component that provides slash command functionality for inserting
  different types of content blocks (headings, lists, etc.) into the editor.

  The menu is triggered by typing "/" and filters available options based on the
  user's query string, matching against option titles and keywords.

  @example
  ```svelte
  <Composer {initialConfig}>
    ...
    <ComponentPickerMenuPlugin />
    ...
  </Composer>
  ```

  //TODO: add tests for slash command
  //TODO: add more slash commands/options
-->
<script lang="ts">import TypeAheadMenu from "../../../components/generic/contextmenu/TypeAheadMenu.svelte";
import Portal from "../../../components/generic/portal/Portal.svelte";
import ComponentPickerMenuItem from "./ComponentPickerMenuItem.svelte";
import { getBaseOptions, getDynamicOptions } from "./getOptions.js";
import { useBasicTypeaheadTriggerMatch } from "../../../components/generic/contextmenu/typeAheadMenuHelpers.js";
import { getEditor } from "../../composerContext.js";
const editor = getEditor();
let queryString = $state(null);
const checkForTriggerMatch = useBasicTypeaheadTriggerMatch("/", {
  allowWhitespace: true,
  minLength: 0
});
let options = $state([]);
const baseOptions = getBaseOptions(
  editor
  /*, showModal*/
);
$effect(() => {
  if (!queryString) {
    options = baseOptions;
    return;
  }
  const regex = new RegExp(queryString, "i");
  options = [
    ...getDynamicOptions(editor, queryString),
    ...baseOptions.filter(
      (option) => regex.test(option.title) || option.keywords.some((keyword) => regex.test(keyword))
    )
  ];
});
const onSelectOption = (selectedOption, nodeToRemove, closeMenu, matchingString) => {
  editor.update(() => {
    nodeToRemove?.remove();
    selectedOption.onSelect(matchingString);
    closeMenu();
  });
};
</script>

{#snippet menuRenderFn(
  anchorElementRef: HTMLElement | null,
  {
    selectedIndex,
    selectOptionAndCleanUp,
  }: {
    selectedIndex: {value: number | null};
    selectOptionAndCleanUp: (option: ComponentPickerOption) => void;
  },
)}
  {#if anchorElementRef && options.length}
    <Portal target={anchorElementRef}>
      <div class="typeahead-popover component-picker-menu svelte-lexical">
        <ul>
          {#each options as option, i (option.key)}
            <ComponentPickerMenuItem
              index={i}
              isSelected={selectedIndex.value === i}
              onclick={() => {
                selectedIndex.value = i;
                selectOptionAndCleanUp(option);
              }}
              onmouseenter={() => {
                selectedIndex.value = i;
              }}
              {option} />
          {/each}
        </ul>
      </div>
      ,
    </Portal>
  {/if}
{/snippet}

<TypeAheadMenu
  onQueryChange={(value) => {
    queryString = value;
  }}
  {onSelectOption}
  triggerFn={checkForTriggerMatch}
  {options}
  {menuRenderFn} />
