<script lang="ts">import { getActiveEditor, getIsEditable } from "../../core/composerContext.js";
import { getContext } from "svelte";
import { SHORTCUTS } from "./shortcuts.js";
import { toggleItalic } from "../../core/commands/commands.js";
const activeEditor = getActiveEditor();
const isEditable = getIsEditable();
const isItalic = getContext("isItalic");
</script>

<button
  disabled={!$isEditable}
  onclick={() => {
    toggleItalic($activeEditor);
  }}
  class={'toolbar-item spaced ' + ($isItalic ? 'active' : '')}
  title={`Italic (${SHORTCUTS.ITALIC})`}
  type="button"
  aria-label={`Format text as italics. Shortcut: ${SHORTCUTS.ITALIC}`}>
  <i class="format italic"></i>
</button>
