<script lang="ts">import { mergeRegister } from "@lexical/utils";
import { setLocalStateFocus } from "@lexical/yjs";
import {
  BLUR_COMMAND,
  COMMAND_PRIORITY_EDITOR,
  FOCUS_COMMAND
} from "lexical";
import { onMount } from "svelte";
let {
  editor,
  provider,
  name,
  color,
  awarenessData = void 0
} = $props();
onMount(() => {
  return mergeRegister(
    editor.registerCommand(
      FOCUS_COMMAND,
      () => {
        setLocalStateFocus(provider, name, color, true, awarenessData || {});
        return false;
      },
      COMMAND_PRIORITY_EDITOR
    ),
    editor.registerCommand(
      BLUR_COMMAND,
      () => {
        setLocalStateFocus(provider, name, color, false, awarenessData || {});
        return false;
      },
      COMMAND_PRIORITY_EDITOR
    )
  );
});
</script>
