<script lang="ts">import { FocusEditor } from "../../../core/commands/commands.js";
import { getEditor } from "../../../core/composerContext.js";
import CloseCircleButton from "../../generic/button/CloseCircleButton.svelte";
import ModalDialog from "../../generic/dialog/ModalDialog.svelte";
import ColorPicker from "./ColorPicker.svelte";
let onChange;
const editor = getEditor();
let { color, title, showModal = $bindable(false) } = $props();
export function open(onChangeCallback, initialColor) {
  if (initialColor) {
    color = initialColor;
  }
  onChange = onChangeCallback;
  showModal = true;
}
function close() {
  showModal = false;
  FocusEditor(editor);
}
function onColorChange(value) {
  if (onChange) {
    onChange(value, true);
  }
}
</script>

<ModalDialog bind:showModal>
  <CloseCircleButton onclick={close} />

  <div class="modal">
    <h2 class="Modal__title">{title}</h2>
    <div class="Modal__content">
      <ColorPicker {color} onChange={onColorChange} />
    </div>
  </div>
</ModalDialog>
