<script lang="ts">import { CAN_REDO_COMMAND, COMMAND_PRIORITY_CRITICAL } from "lexical";
import { onMount } from "svelte";
import {
  getEditor,
  getIsEditable,
  getActiveEditor
} from "../../core/composerContext.js";
import { IS_APPLE } from "@lexical/utils";
import { redo } from "../../core/commands/commands.js";
const editor = getEditor();
const activeEditor = getActiveEditor();
const isEditable = getIsEditable();
let canRedo = $state(false);
onMount(() => {
  return editor.registerCommand(
    CAN_REDO_COMMAND,
    (payload) => {
      canRedo = payload;
      return false;
    },
    COMMAND_PRIORITY_CRITICAL
  );
});
</script>

<button
  disabled={!canRedo || !$isEditable}
  onclick={() => {
    redo($activeEditor);
  }}
  title={IS_APPLE ? 'Redo (⇧⌘Z)' : 'Redo (Ctrl+Y)'}
  type="button"
  class="toolbar-item"
  aria-label="Redo">
  <i class="format redo"></i>
</button>
