<!-- eslint-disable-next-line svelte/no-unused-svelte-ignore -->
<!-- svelte-ignore state_referenced_locally -->
<script lang="ts">import { mergeRegister } from "@lexical/utils";
import {
  CONNECTED_COMMAND,
  initLocalState,
  syncCursorPositions,
  syncLexicalUpdateToYjs,
  syncYjsChangesToLexical,
  TOGGLE_CONNECT_COMMAND
} from "@lexical/yjs";
import {
  $createParagraphNode as createParagraphNode,
  $getRoot as getRoot,
  $getSelection as getSelection,
  COMMAND_PRIORITY_EDITOR,
  HISTORY_MERGE_TAG,
  SKIP_COLLAB_TAG
} from "lexical";
import { UndoManager } from "yjs";
import { onMount } from "svelte";
let {
  editor,
  id,
  provider,
  binding = $bindable(),
  docMap,
  name,
  color,
  shouldBootstrap,
  cursorsContainerRef = null,
  initialEditorState = null,
  awarenessData = void 0,
  syncCursorPositionsFn = syncCursorPositions
} = $props();
let isReloadingDoc = false;
let doc = docMap.get(id);
const connect = () => {
  return provider.connect();
};
const disconnect = () => {
  try {
    provider.disconnect();
  } catch {
  }
};
function initializeProviderAndConnect() {
  const { root } = binding;
  const { awareness } = provider;
  const onStatus = ({ status }) => {
    editor.dispatchCommand(CONNECTED_COMMAND, status === "connected");
  };
  const onSync = (isSynced) => {
    if (shouldBootstrap && isSynced && root.isEmpty() && root._xmlText._length === 0 && isReloadingDoc === false) {
      initializeEditor(editor, initialEditorState);
    }
    isReloadingDoc = false;
  };
  const onAwarenessUpdate = () => {
    syncCursorPositionsFn(binding, provider);
  };
  const onYjsTreeChanges = (events, transaction) => {
    const origin = transaction.origin;
    if (origin !== binding) {
      const isFromUndoManger = origin instanceof UndoManager;
      syncYjsChangesToLexical(
        binding,
        provider,
        events,
        isFromUndoManger,
        syncCursorPositionsFn
      );
    }
  };
  initLocalState(
    provider,
    name,
    color,
    document.activeElement === editor.getRootElement(),
    awarenessData || {}
  );
  const onProviderDocReload = (ydoc) => {
    clearEditorSkipCollab(editor, binding);
    doc = ydoc;
    docMap.set(id, ydoc);
    isReloadingDoc = true;
  };
  provider.on("reload", onProviderDocReload);
  provider.on("status", onStatus);
  provider.on("sync", onSync);
  awareness.on("update", onAwarenessUpdate);
  root.getSharedType().observeDeep(onYjsTreeChanges);
  const removeListener = editor.registerUpdateListener(
    ({
      prevEditorState,
      editorState,
      dirtyLeaves,
      dirtyElements,
      normalizedNodes,
      tags
    }) => {
      if (tags.has(SKIP_COLLAB_TAG) === false) {
        syncLexicalUpdateToYjs(
          binding,
          provider,
          prevEditorState,
          editorState,
          dirtyElements,
          dirtyLeaves,
          normalizedNodes,
          tags
        );
      }
    }
  );
  const connectionPromise = connect();
  return () => {
    if (isReloadingDoc === false) {
      if (connectionPromise) {
        connectionPromise.then(disconnect);
      } else {
        disconnect();
      }
    }
    provider.off("sync", onSync);
    provider.off("status", onStatus);
    provider.off("reload", onProviderDocReload);
    awareness.off("update", onAwarenessUpdate);
    root.getSharedType().unobserveDeep(onYjsTreeChanges);
    docMap.delete(id);
    removeListener();
  };
}
function createCursorsContainer() {
  const ref = document.createElement("div");
  const target = cursorsContainerRef || document.body;
  target.appendChild(ref);
  binding.cursorsContainer = ref;
  return () => {
    if (ref?.parentNode) {
      ref.parentNode?.removeChild(ref);
    }
  };
}
onMount(() => {
  return mergeRegister(
    createCursorsContainer(),
    initializeProviderAndConnect(),
    editor.registerCommand(
      TOGGLE_CONNECT_COMMAND,
      (payload) => {
        const shouldConnect = payload;
        if (shouldConnect) {
          console.log("Collaboration connected!");
          connect();
        } else {
          console.log("Collaboration disconnected!");
          disconnect();
        }
        return true;
      },
      COMMAND_PRIORITY_EDITOR
    )
  );
});
function initializeEditor(editor2, initialEditorState2) {
  editor2.update(
    () => {
      const root = getRoot();
      if (root.isEmpty()) {
        if (initialEditorState2) {
          switch (typeof initialEditorState2) {
            case "string": {
              const parsedEditorState = editor2.parseEditorState(initialEditorState2);
              editor2.setEditorState(parsedEditorState, {
                tag: HISTORY_MERGE_TAG
              });
              break;
            }
            case "object": {
              editor2.setEditorState(initialEditorState2, {
                tag: HISTORY_MERGE_TAG
              });
              break;
            }
            case "function": {
              editor2.update(
                () => {
                  const root1 = getRoot();
                  if (root1.isEmpty()) {
                    initialEditorState2(editor2);
                  }
                },
                { tag: HISTORY_MERGE_TAG }
              );
              break;
            }
          }
        } else {
          const paragraph = createParagraphNode();
          root.append(paragraph);
          const { activeElement } = document;
          if (getSelection() !== null || activeElement !== null && activeElement === editor2.getRootElement()) {
            paragraph.select();
          }
        }
      }
    },
    {
      tag: HISTORY_MERGE_TAG
    }
  );
}
function clearEditorSkipCollab(editor2, binding2) {
  editor2.update(
    () => {
      const root = getRoot();
      root.clear();
      root.select();
    },
    {
      tag: SKIP_COLLAB_TAG
    }
  );
  if (binding2.cursors == null) {
    return;
  }
  const cursors = binding2.cursors;
  if (cursors == null) {
    return;
  }
  const cursorsContainer = binding2.cursorsContainer;
  if (cursorsContainer == null) {
    return;
  }
  const cursorsArr = Array.from(cursors.values());
  for (let i = 0; i < cursorsArr.length; i++) {
    const cursor = cursorsArr[i];
    const selection = cursor.selection;
    if (selection && selection.selections != null) {
      const selections = selection.selections;
      for (let j = 0; j < selections.length; j++) {
        cursorsContainer.removeChild(selections[i]);
      }
    }
  }
}
</script>
