<script lang="ts">import { getContext } from "svelte";
import { getActiveEditor, getIsEditable } from "../../core/composerContext.js";
import { SHORTCUTS } from "./shortcuts.js";
import { toggleStrikethrough } from "../../core/commands/commands.js";
const activeEditor = getActiveEditor();
const isEditable = getIsEditable();
const isStrikethrough = getContext("isStrikethrough");
</script>

<button
  disabled={!$isEditable}
  onclick={() => {
    toggleStrikethrough($activeEditor);
  }}
  class={'toolbar-item spaced ' + ($isStrikethrough ? 'active' : '')}
  title={`Strikethrough (${SHORTCUTS.STRIKETHROUGH})`}
  type="button"
  aria-label="Format text with a strikethrough">
  <i class="format strikethrough"></i>
</button>
