<script lang="ts">import {
  $getTableAndElementByKey as getTableAndElementByKey,
  $getTableColumnIndexFromTableCellNode as getTableColumnIndexFromTableCellNode,
  getTableElement,
  $getTableRowIndexFromTableCellNode as getTableRowIndexFromTableCellNode,
  $insertTableColumnAtSelection as insertTableColumnAtSelection,
  $insertTableRowAtSelection as insertTableRowAtSelection,
  $isTableCellNode as isTableCellNode,
  $isTableNode as isTableNode,
  TableCellNode,
  TableNode,
  TableRowNode
} from "@lexical/table";
import {
  $findMatchingParent as findMatchingParent,
  isHTMLElement,
  mergeRegister
} from "@lexical/utils";
import {
  $getNearestNodeFromDOMNode as getNearestNodeFromDOMNode
} from "lexical";
import { useDebounce } from "../CodeBlock/CodeActionMenuPlugin/utils.js";
import { getEditor, getIsEditable } from "../../composerContext.js";
import { onDestroy, onMount } from "svelte";
import { writable } from "svelte/store";
import { CAN_USE_DOM } from "@lexical/utils";
import { getThemeSelector } from "../util/getThemeSelector.js";
const BUTTON_WIDTH_PX = 20;
const editor = getEditor();
const isEditable = getIsEditable();
let isShownRow = writable(false);
let isShownColumn = writable(false);
let shouldListenMouseMove = $state(false);
let position = writable("");
const tableSetRef = /* @__PURE__ */ new Set();
let tableCellDOMNodeRef = null;
let { anchorElem } = $props();
function getMouseInfo(event) {
  const target = event.target;
  if (isHTMLElement(target)) {
    const themeSelector = getThemeSelector(editor._config.theme.tableCell);
    const tableDOMNode = target.closest(
      `td${themeSelector}, th${themeSelector}`
    );
    const isOutside = !(tableDOMNode || target.closest(
      `button${getThemeSelector(editor._config.theme.tableAddRows)}`
    ) || target.closest(
      `button${getThemeSelector(editor._config.theme.tableAddColumns)}`
    ) || target.closest("div.SL_Theme__tableCellResizer"));
    return { isOutside, tableDOMNode };
  } else {
    return { isOutside: true, tableDOMNode: null };
  }
}
const debouncedOnMouseMove = useDebounce(
  (event) => {
    const { isOutside, tableDOMNode } = getMouseInfo(event);
    if (isOutside) {
      $isShownRow = false;
      $isShownColumn = false;
      return;
    }
    if (!tableDOMNode) {
      return;
    }
    tableCellDOMNodeRef = tableDOMNode;
    let hoveredRowNode = null;
    let hoveredColumnNode = null;
    let tableDOMElement = null;
    editor.getEditorState().read(
      () => {
        const maybeTableCell = getNearestNodeFromDOMNode(tableDOMNode);
        if (isTableCellNode(maybeTableCell)) {
          const table = findMatchingParent(
            maybeTableCell,
            (node) => isTableNode(node)
          );
          if (!isTableNode(table)) {
            return;
          }
          tableDOMElement = getTableElement(
            table,
            editor.getElementByKey(table.getKey())
          );
          if (tableDOMElement) {
            const rowCount = table.getChildrenSize();
            const colCount = table.getChildAtIndex(0)?.getChildrenSize();
            const rowIndex = getTableRowIndexFromTableCellNode(maybeTableCell);
            const colIndex = getTableColumnIndexFromTableCellNode(maybeTableCell);
            if (rowIndex === rowCount - 1) {
              hoveredRowNode = maybeTableCell;
            } else if (colIndex === colCount - 1) {
              hoveredColumnNode = maybeTableCell;
            }
          }
        }
      },
      { editor }
    );
    if (tableDOMElement) {
      const {
        width: tableElemWidth,
        y: tableElemY,
        right: tableElemRight,
        left: tableElemLeft,
        bottom: tableElemBottom,
        height: tableElemHeight
      } = tableDOMElement.getBoundingClientRect();
      const parentElement = tableDOMElement.parentElement;
      let tableHasScroll = false;
      if (parentElement && parentElement.classList.contains(
        "PlaygroundEditorTheme__tableScrollableWrapper"
      )) {
        tableHasScroll = parentElement.scrollWidth > parentElement.clientWidth;
      }
      const { y: editorElemY, left: editorElemLeft } = anchorElem.getBoundingClientRect();
      if (hoveredRowNode) {
        $isShownColumn = false;
        $isShownRow = true;
        $position = `height: ${BUTTON_WIDTH_PX}px; left: ${tableHasScroll && parentElement ? parentElement.offsetLeft : tableElemLeft - editorElemLeft}px; top: ${tableElemBottom - editorElemY + 5}px; width: ${tableHasScroll && parentElement ? parentElement.offsetWidth : tableElemWidth}px;`;
      } else if (hoveredColumnNode) {
        $isShownColumn = true;
        $isShownRow = false;
        $position = `height: ${tableElemHeight}px; left: ${tableElemRight - editorElemLeft + 5}px; top: ${tableElemY - editorElemY}px; width: ${BUTTON_WIDTH_PX}px;`;
      }
    }
  },
  50,
  250
);
$effect(() => {
  if (!CAN_USE_DOM) return;
  if (!shouldListenMouseMove) {
    $isShownRow = false;
    $isShownColumn = false;
    debouncedOnMouseMove.cancel();
    document.removeEventListener("mousemove", debouncedOnMouseMove);
    return;
  }
  document.addEventListener("mousemove", debouncedOnMouseMove);
  return () => document.removeEventListener("mousemove", debouncedOnMouseMove);
});
onDestroy(() => {
  $isShownRow = false;
  $isShownColumn = false;
  debouncedOnMouseMove.cancel();
  if (CAN_USE_DOM) {
    document.removeEventListener("mousemove", debouncedOnMouseMove);
  }
});
onMount(() => {
  const tableResizeObserver = new ResizeObserver(() => {
    $isShownRow = false;
    $isShownColumn = false;
  });
  return mergeRegister(
    editor.registerMutationListener(
      TableNode,
      (mutations) => {
        editor.getEditorState().read(
          () => {
            let resetObserver = false;
            for (const [key, type] of mutations) {
              switch (type) {
                case "created": {
                  tableSetRef.add(key);
                  resetObserver = true;
                  break;
                }
                case "destroyed": {
                  tableSetRef.delete(key);
                  resetObserver = true;
                  break;
                }
                default:
                  break;
              }
            }
            if (resetObserver) {
              tableResizeObserver.disconnect();
              for (const tableKey of tableSetRef) {
                const { tableElement } = getTableAndElementByKey(tableKey);
                tableResizeObserver.observe(tableElement);
              }
              shouldListenMouseMove = tableSetRef.size > 0;
            }
          },
          { editor }
        );
      },
      { skipInitialization: false }
    )
  );
});
const insertAction = (insertRow) => {
  editor.update(() => {
    if (tableCellDOMNodeRef) {
      const maybeTableNode = getNearestNodeFromDOMNode(tableCellDOMNodeRef);
      maybeTableNode?.selectEnd();
      if (insertRow) {
        insertTableRowAtSelection();
        $isShownRow = false;
      } else {
        insertTableColumnAtSelection();
        $isShownColumn = false;
      }
    }
  });
};
</script>

{#if $isEditable}
  {#if $isShownRow}
    <!-- svelte-ignore a11y_consider_explicit_label -->
    <button
      type="button"
      class={`${editor._config.theme.tableAddRows}`}
      style={$position}
      onclick={() => insertAction(true)}>
    </button>
  {/if}
  {#if $isShownColumn}
    <!-- svelte-ignore a11y_consider_explicit_label -->
    <button
      type="button"
      class={`${editor._config.theme.tableAddColumns}`}
      style={$position}
      onclick={() => insertAction(false)}>
    </button>
  {/if}
{/if}
